	<T extends Throwable> void expecting(Class<object> cls, ExceptionalCallback<T> cb)
    {
		try {
			cb.call();
			fail("Did not get expected exception %s".formatted(cls.getSimpleName()));
		}
		catch (Throwable e) {
			if (cls.isInstance(e)) {
				return;
			}
			throw e;
		}
	}

