	/**
	 * i.e., an expression is placed inside the probe vs. just a varnode
	 * 
	 * @throws Exception because
	 */
	/* @Test */
	public void testProbeUnique()
    {
		// Note: r12 should be 8 at this address
		placeInject(addressOfLoad, """
				emu_probe(r12 + 0x1234);
				emu_exec_decoded();
				""");

